// Supply-chain guard for the committed generated WASM artifacts.
//
// src/wasm/wrapper/heic-decoder.js (Emscripten glue) and
// src/wasm/public/heic-decoder.wasm (decoder binary) are generated by
// `npm run build:wasm` and committed. This script verifies they still match
// the reviewed build (SHA-256) and that the glue contains no dynamic code
// evaluation (the CSP guarantee from -s DYNAMIC_EXECUTION=0).
//
// Usage:
//   node build-scripts/verify-wasm-artifacts.mjs          # check (CI)
//   node build-scripts/verify-wasm-artifacts.mjs --write  # after an intentional `npm run build:wasm`
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MANIFEST = path.join(ROOT, 'build-scripts', 'wasm-artifacts.json');
const ARTIFACTS = {
  'src/wasm/public/heic-decoder.wasm': 'wasm',
  'src/wasm/wrapper/heic-decoder.js': 'glue',
};

// Must stay false: the library is built with -s DYNAMIC_EXECUTION=0 so no
// eval()/new Function() is ever emitted (CSP-compliance requirement).
const FORBIDDEN_PATTERNS = [
  { label: 'eval(', pattern: /(^|[^\w.$])eval\s*\(/ },
  { label: 'new Function(', pattern: /new\s+Function\s*\(/ },
];

function sha256(file) {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

const writeMode = process.argv.includes('--write');

if (writeMode) {
  const manifest = {};
  for (const rel of Object.keys(ARTIFACTS)) {
    const file = path.join(ROOT, rel);
    if (!existsSync(file)) {
      console.error(`Error: ${rel} is missing. Run \`npm run build:wasm\` (requires Docker) first.`);
      process.exit(1);
    }
    manifest[rel] = sha256(file);
  }
  writeFileSync(MANIFEST, `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(`Wrote ${path.relative(ROOT, MANIFEST)}:`);
  for (const [rel, hash] of Object.entries(manifest)) {
    console.log(`  ${hash}  ${rel}`);
  }
  process.exit(0);
}

if (!existsSync(MANIFEST)) {
  console.error(`Error: ${path.relative(ROOT, MANIFEST)} is missing. Generate it with:\n  node build-scripts/verify-wasm-artifacts.mjs --write`);
  process.exit(1);
}

const expected = JSON.parse(readFileSync(MANIFEST, 'utf8'));
const errors = [];

for (const [rel, kind] of Object.entries(ARTIFACTS)) {
  const file = path.join(ROOT, rel);
  if (!existsSync(file)) {
    errors.push(`${rel} is missing — run \`npm run build:wasm\` (requires Docker) and commit the artifacts.`);
    continue;
  }
  const actual = sha256(file);
  if (expected[rel] !== actual) {
    errors.push(
      `${rel} hash mismatch.\n  expected: ${expected[rel]}\n  actual:   ${actual}\n` +
        'If this change came from an intentional `npm run build:wasm`, update the pinned hashes:\n' +
        '  node build-scripts/verify-wasm-artifacts.mjs --write'
    );
  }
  if (kind === 'glue') {
    const glue = readFileSync(file, 'utf8');
    for (const { label, pattern } of FORBIDDEN_PATTERNS) {
      if (pattern.test(glue)) {
        errors.push(`${rel} contains ${label} — the CSP guarantee (-s DYNAMIC_EXECUTION=0) is broken.`);
      }
    }
  }
}

if (errors.length > 0) {
  console.error(`WASM artifact verification FAILED:\n\n${errors.map((e) => `- ${e}`).join('\n\n')}`);
  process.exit(1);
}

console.log('WASM artifacts verified: hashes match and glue is free of eval()/new Function().');
